return {api_version=1,id="OG_176",name="Shadow Strike",text="Deal $5 damage to an undamaged character.",set="OG",type="spell",class="rogue",rarity="common",spell_school="shadow",cost=3,target_mode="required",targets=function(ctx)local r={};for _,e in ipairs(ctx:characters())do if ctx:entity(e).damage==0 then r[#r+1]=e end end return r end,on_play=function(ctx,self,target)ctx:damage(target,5)end}
